create extension if not exists pgcrypto;

create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.cheque_templates (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, background_path text, layout jsonb not null default '{}'::jsonb, printer_settings jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.cheques (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, template_id uuid references public.cheque_templates(id) on delete set null, cheque_number text, bank_name text, account_reference text, cheque_date text, payee text not null default '', amount numeric(18,2) not null default 0, amount_in_words text, status text not null default 'draft' check(status in ('draft','printed','reprinted','cancelled','void')), notes text not null default '', layout_snapshot jsonb not null default '{}'::jsonb, first_printed_at timestamptz, last_printed_at timestamptz, print_count integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.print_history (id uuid primary key default gen_random_uuid(), cheque_id uuid not null references public.cheques(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, print_number integer not null default 1, printed_at timestamptz not null default now(), layout_snapshot jsonb not null default '{}'::jsonb, notes text not null default '');
create table if not exists public.printer_settings (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null default 'Default printer', settings jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists cheques_user_created_idx on public.cheques(user_id,created_at desc); create index if not exists print_history_cheque_idx on public.print_history(cheque_id,printed_at desc);
alter table public.profiles enable row level security; alter table public.cheque_templates enable row level security; alter table public.cheques enable row level security; alter table public.print_history enable row level security; alter table public.printer_settings enable row level security;
revoke all on public.profiles,public.cheque_templates,public.cheques,public.print_history,public.printer_settings from anon; grant select,insert,update,delete on public.profiles,public.cheque_templates,public.cheques,public.print_history,public.printer_settings to authenticated;
create policy "profiles own" on public.profiles for all to authenticated using ((select auth.uid())=id) with check ((select auth.uid())=id);
create policy "templates own" on public.cheque_templates for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "cheques own" on public.cheques for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "print history own" on public.print_history for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "printer settings own" on public.printer_settings for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'name') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into storage.buckets(id,name,public) values('cheque-backgrounds','cheque-backgrounds',false) on conflict(id) do nothing;
create policy "backgrounds own select" on storage.objects for select to authenticated using(bucket_id='cheque-backgrounds' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "backgrounds own insert" on storage.objects for insert to authenticated with check(bucket_id='cheque-backgrounds' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "backgrounds own update" on storage.objects for update to authenticated using(bucket_id='cheque-backgrounds' and (storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id='cheque-backgrounds' and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "backgrounds own delete" on storage.objects for delete to authenticated using(bucket_id='cheque-backgrounds' and (storage.foldername(name))[1]=(select auth.uid())::text);
